package ru.transferservis.admin.ui;
import android.content.Context;
import android.content.Intent;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.*;
import com.google.android.material.appbar.MaterialToolbar;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import ru.transferservis.admin.R;
import ru.transferservis.admin.data.*;

/** OWNER rule authoring only. No per-vehicle class, admission, persistence or automatic retry. */
public final class VehicleRuleActivity extends AppCompatActivity {
    private VehicleRuleRepository repository;private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
    private String account;private long scope;private int generation;private boolean started,busy;
    private AdminAccess access;private VehicleRuleAction.Snapshot snapshot;private VehicleRuleAction uncertain;private AlertDialog confirmation;
    private final List<EditText> conditions=new ArrayList<>();
    private static final String[] CLASSES={"","comfort","business","minivan"},BODIES={"sedan","crossover","minivan","other"};
    private static final int[] BODY_IDS={R.id.rulesSedan,R.id.rulesCrossover,R.id.rulesMinivan,R.id.rulesOther};
    public static Intent intent(Context c,String account){return new Intent(c,VehicleRuleActivity.class).putExtra("account",account);}
    @Override protected void onCreate(Bundle saved){getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);super.onCreate(null);setContentView(R.layout.activity_vehicle_rules);account=getIntent().getStringExtra("account");getIntent().removeExtra("account");if(saved!=null||account==null||!account.matches("staff_[A-Za-z0-9_-]{8,94}")){finish();return;}
        View root=findViewById(R.id.rulesRoot);root.setSaveFromParentEnabled(false);getWindow().getDecorView().setFilterTouchesWhenObscured(true);if(Build.VERSION.SDK_INT>=30)root.setImportantForContentCapture(View.IMPORTANT_FOR_CONTENT_CAPTURE_NO_EXCLUDE_DESCENDANTS);
        WindowCompat.setDecorFitsSystemWindows(getWindow(),false);boolean light=(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)!=android.content.res.Configuration.UI_MODE_NIGHT_YES;WindowInsetsControllerCompat bars=WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView());bars.setAppearanceLightStatusBars(light);bars.setAppearanceLightNavigationBars(light);
        ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets b=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());int p=dp(16);v.setPadding(p+b.left,b.top,p+b.right,p+b.bottom);return insets;});ViewCompat.requestApplyInsets(root);
        repository=new VehicleRuleRepository(this);((MaterialToolbar)findViewById(R.id.rulesToolbar)).setNavigationOnClickListener(v->finish());((Spinner)findViewById(R.id.rulesClass)).setAdapter(ArrayAdapter.createFromResource(this,R.array.rules_classes,android.R.layout.simple_spinner_dropdown_item));
        for(int id:new int[]{R.id.rulesConfirm,R.id.rulesRetry,R.id.rulesRead,R.id.rulesAddCondition,R.id.rulesNullBody,R.id.rulesSedan,R.id.rulesCrossover,R.id.rulesMinivan,R.id.rulesOther,R.id.rulesClass})findViewById(id).setFilterTouchesWhenObscured(true);
        findViewById(R.id.rulesRead).setOnClickListener(v->read());findViewById(R.id.rulesConfirm).setOnClickListener(v->prepare());findViewById(R.id.rulesRetry).setOnClickListener(v->{if(uncertain!=null&&!busy)confirm(uncertain);});findViewById(R.id.rulesAddCondition).setOnClickListener(v->{if(!busy&&conditions.size()<32)addCondition("");});render();
    }
    @Override protected void onStart(){super.onStart();started=true;if(repository!=null)authorize();}
    @Override protected void onStop(){started=false;generation++;handler.removeCallbacksAndMessages(null);if(repository!=null)repository.cancel();scope=0;busy=false;access=null;uncertain=null;wipe(true);message(0);render();super.onStop();}
    @Override protected void onDestroy(){if(repository!=null)repository.cancel();executor.shutdownNow();handler.removeCallbacksAndMessages(null);super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.clear();}
    private boolean active(int ticket){return started&&ticket==generation&&!isFinishing();}
    private void authorize(){if(!started||busy)return;wipe(true);uncertain=null;access=null;try{scope=repository.bind(account);}catch(IOException e){failure(e,false);return;}busy=true;message(R.string.assessment_loading);render();int ticket=++generation;long expected=scope;
        executor.execute(()->{try{AdminAccess a=repository.access(expected);runOnUiThread(()->{if(!active(ticket))return;if(!repository.current(expected)){failure(new IOException(),false);return;}busy=false;access=a;armMfa();message(0);render();});}catch(IOException|RuntimeException e){runOnUiThread(()->{if(active(ticket))failure(e,false);});}});
    }
    private void read(){if(!started||busy)return;if(access==null){authorize();return;}try{String make=uncertain==null?VehicleAssessment.text(value(R.id.rulesMake),80):uncertain.make,model=uncertain==null?VehicleAssessment.text(value(R.id.rulesModel),80):uncertain.model;wipe(false);busy=true;message(R.string.assessment_loading);render();int ticket=++generation;long expected=scope;
        executor.execute(()->{try{VehicleRuleRepository.Read r=repository.read(expected,make,model);runOnUiThread(()->{if(!active(ticket))return;if(!repository.current(expected)){failure(new IOException(),false);return;}busy=false;access=r.access;armMfa();if(uncertain==null){snapshot=r.snapshot;text(R.id.rulesMake,make);text(R.id.rulesModel,model);populate();message(0);}else{text(R.id.rulesSummary,summary(uncertain));text(R.id.rulesMessage,getString(R.string.rules_uncertain)+"\n"+current(r.snapshot));}render();});}catch(IOException|RuntimeException e){runOnUiThread(()->{if(active(ticket))failure(e,false);});}});
        }catch(IOException e){message(R.string.rules_required);}}
    private String current(VehicleRuleAction.Snapshot s){VehicleClassification.Rule r=s.rule;return r==null?getString(R.string.rules_empty):getString(R.string.rules_current,r.version,r.make,r.model,className(r.vehicleClass),r.minYear);}
    private void populate(){VehicleClassification.Rule r=snapshot.rule;text(R.id.rulesSummary,current(snapshot));if(r==null)return;text(R.id.rulesYear,Long.toString(r.minYear));((Spinner)findViewById(R.id.rulesClass)).setSelection(Arrays.asList(CLASSES).indexOf(r.vehicleClass));check(R.id.rulesNullBody).setChecked(r.allowedBodyTypes==null);if(r.allowedBodyTypes!=null)for(int i=0;i<BODY_IDS.length;i++)check(BODY_IDS[i]).setChecked(r.allowedBodyTypes.contains(BODIES[i]));for(VehicleClassification.Condition c:r.conditions)addCondition(c.text);}
    private void addCondition(String value){LinearLayout list=findViewById(R.id.rulesConditions),row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setSaveEnabled(false);TextView label=new TextView(this);label.setText(getString(R.string.rules_condition,conditions.size()+1));row.addView(label);EditText field=new EditText(this);field.setSingleLine(true);field.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);field.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1000)});field.setMinHeight(dp(48));field.setSaveEnabled(false);field.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);field.setHint(R.string.rules_conditions);field.setText(value);row.addView(field);conditions.add(field);Button remove=new Button(this);remove.setText(R.string.rules_remove_condition);remove.setMinHeight(dp(48));remove.setSaveEnabled(false);remove.setFilterTouchesWhenObscured(true);remove.setOnClickListener(v->{field.setText("");conditions.remove(field);list.removeView(row);});row.addView(remove);list.addView(row);}
    private void prepare(){if(busy||snapshot==null||uncertain!=null)return;try{List<String> bodies=new ArrayList<>(),rows=new ArrayList<>();for(int i=0;i<BODY_IDS.length;i++)if(check(BODY_IDS[i]).isChecked())bodies.add(BODIES[i]);boolean legacy=check(R.id.rulesNullBody).isChecked();if(legacy&&!bodies.isEmpty())throw new IOException();for(EditText field:conditions)rows.add(field.getText().toString());VehicleRuleAction a=VehicleRuleAction.create(access,snapshot,value(R.id.rulesMake),value(R.id.rulesModel),value(R.id.rulesYear),CLASSES[((Spinner)findViewById(R.id.rulesClass)).getSelectedItemPosition()],legacy?null:bodies,rows,value(R.id.rulesReason));confirm(a);}catch(IOException|RuntimeException e){message(R.string.rules_required);}}
    private String summary(VehicleRuleAction a){StringBuilder bodies=new StringBuilder();if(a.bodies!=null)for(String body:a.bodies){if(bodies.length()>0)bodies.append(", ");bodies.append(getString("sedan".equals(body)?R.string.classification_sedan:"crossover".equals(body)?R.string.classification_crossover:"minivan".equals(body)?R.string.classification_minivan:R.string.classification_other));}
        return getString(R.string.rules_summary,a.make,a.model,a.snapshot.rule==null?getString(R.string.assessment_none):a.snapshot.rule.version,a.minYear,className(a.vehicleClass),a.bodies==null?getString(R.string.rules_null_label):bodies.toString(),a.conditions.isEmpty()?getString(R.string.assessment_none):android.text.TextUtils.join("\n",a.conditions),a.reason);}
    private void confirm(VehicleRuleAction a){if(!started||busy||!repository.current(a.scope)){failure(new IOException(),false);return;}dismiss();confirmation=new AlertDialog.Builder(this).setTitle(R.string.rules_confirm_title).setMessage(summary(a)).setNegativeButton(R.string.assessment_no,null).setPositiveButton(R.string.assessment_yes,(d,w)->send(a)).create();if(confirmation.getWindow()!=null)confirmation.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);confirmation.show();confirmation.getButton(AlertDialog.BUTTON_POSITIVE).setFilterTouchesWhenObscured(true);}
    private void send(VehicleRuleAction a){if(!started||busy)return;dismiss();uncertain=a;wipe(true);busy=true;message(R.string.assessment_saving);render();int ticket=++generation;executor.execute(()->{try{VehicleClassification.Rule r=repository.apply(a);runOnUiThread(()->{if(!active(ticket))return;if(!repository.current(a.scope)){failure(new IOException(),true);return;}busy=false;uncertain=null;wipe(true);text(R.id.rulesSummary,getString(R.string.rules_created,r.version,r.make,r.model,className(r.vehicleClass),r.minYear));message(0);render();});}catch(IOException|RuntimeException e){runOnUiThread(()->{if(active(ticket))failure(e,true);});}});}
    private void failure(Throwable e,boolean write){busy=false;int status=e instanceof AdminApiClient.Failure?((AdminApiClient.Failure)e).status:0;boolean denied=scope==0||repository==null||!repository.current(scope)||status==401||status==403;
        if(denied){uncertain=null;access=null;wipe(true);message(R.string.assessment_permission);}else if(write&&!(status>=400&&status<500&&status!=408)){wipe(true);text(R.id.rulesSummary,summary(uncertain));message(R.string.rules_uncertain);}else{if(write)uncertain=null;wipe(false);if(uncertain!=null)text(R.id.rulesSummary,summary(uncertain));message(status==409?R.string.rules_changed:write?R.string.rules_rejected:R.string.assessment_failed);}render();}
    private void armMfa(){handler.removeCallbacksAndMessages(null);handler.postDelayed(()->{if(started){generation++;repository.cancel();scope=0;busy=false;access=null;uncertain=null;wipe(true);message(R.string.assessment_permission);render();}},Math.max(1,access.mfaExpiresAt-System.currentTimeMillis()));}
    private void render(){if(findViewById(R.id.rulesRoot)==null)return;boolean permitted=access!=null&&access.canManageVehicleRules(),free=started&&!busy&&permitted&&uncertain==null;findViewById(R.id.rulesProgress).setVisibility(busy?View.VISIBLE:View.GONE);findViewById(R.id.rulesTarget).setVisibility(free?View.VISIBLE:View.GONE);findViewById(R.id.rulesForm).setVisibility(free&&snapshot!=null?View.VISIBLE:View.GONE);findViewById(R.id.rulesConfirm).setEnabled(free&&snapshot!=null);findViewById(R.id.rulesRetry).setVisibility(started&&!busy&&uncertain!=null?View.VISIBLE:View.GONE);findViewById(R.id.rulesRead).setEnabled(started&&!busy);((TextView)findViewById(R.id.rulesRead)).setText(uncertain==null?R.string.rules_read:R.string.rules_read_uncertain);}
    private void wipe(boolean target){dismiss();snapshot=null;for(EditText field:conditions)field.setText("");conditions.clear();((LinearLayout)findViewById(R.id.rulesConditions)).removeAllViews();text(R.id.rulesYear,"");text(R.id.rulesReason,"");text(R.id.rulesSummary,"");if(target){text(R.id.rulesMake,"");text(R.id.rulesModel,"");}((Spinner)findViewById(R.id.rulesClass)).setSelection(0);for(int id:BODY_IDS)check(id).setChecked(false);check(R.id.rulesNullBody).setChecked(false);}
    private void dismiss(){if(confirmation!=null){confirmation.dismiss();confirmation=null;}}
    private CheckBox check(int id){return findViewById(id);}private String value(int id){return ((TextView)findViewById(id)).getText().toString();}private void text(int id,String value){((TextView)findViewById(id)).setText(value);}private void message(int id){text(R.id.rulesMessage,id==0?"":getString(id));}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private String className(String c){return getString("comfort".equals(c)?R.string.classification_comfort:"business".equals(c)?R.string.classification_business:R.string.classification_minivan);}
}
